}
const toMin = hhmm => { const [h, m] = hhmm.split(":").map(Number); return h * 60 + m; };
const horaPedida = solicitadoKey ? solicitadoKey.slice(11, 16) : null;

let alternativas = [...(slotsPorDia[dia] || [])];
if (horaPedida) {
  alternativas.sort((a, b) =>
    Math.abs(toMin(a.start.slice(11, 16)) - toMin(horaPedida)) -
