parameters.jsCode:
// Busca a midia do lead cruzando por ID (prioridade) e por TELEFONE (fallback/checagem),
// vindos do node "trigger". Preserva a estrutura original do item (input[0].json.dados)
// buscando ela DIRETO pelo nome do node que a produziu, nao pelo que chega aqui -
// porque o node "Mailing - Ler Dados" (Google Sheets) substitui os itens que passam
// por ele pelas proprias linhas da planilha, entao usar $input aqui pegaria as
// linhas de mailing em vez do lead.
const idLead = $('trigger').first().json.id;
const telefoneLead = $('trigger').first().json.telefone;
const mailingRows = $('Mailing - Ler Dados').all().map(i => i.json);

const MIDIA_LABELS = {
  1: 'Outbound Bank',
  2: 'Parcerias',
  4: 'Outbound Raul',
  10: 'Desconhecido',
  14: 'Inbound',
  15: 'Remarketing'
};

function normalizarTelefone(tel) {
  if (!tel) return '';
  return String(tel).replace(/\D/g, '');
}

function telefonesBatem(a, b) {
  const na = normalizarTelefone(a);
  const nb = normalizarTelefone(b);
  if (na.length < 8 || nb.length < 8) return false;
  // compara só os últimos 8 dígitos, pra ignorar diferença de DDI/DDD entre as fontes
  return na.slice(-8) === nb.slice(-8);
}

const registroPorId = mailingRows.find(m => String(m.id) === String(idLead));
const registroPorTelefone = mailingRows.find(m => telefonesBatem(m.whatsapp, telefoneLead));

const midiaPorId = registroPorId ? Number(registroPorId.midia) : null;
const midiaPorTelefone = registroPorTelefone ? Number(registroPorTelefone.midia) : null;

let midiaCodigo = null;
let midiaConflito = false;

if (midiaPorId !== null && midiaPorTelefone !== null && midiaPorId !== midiaPorTelefone) {
  // os dois acharam registro, mas com mídia diferente -> id manda
  midiaCodigo = midiaPorId;
  midiaConflito = true;
} else if (midiaPorId !== null) {
  midiaCodigo = midiaPorId;
} else if (midiaPorTelefone !== null) {
  midiaCodigo = midiaPorTelefone;
}

const midiaLabel = MIDIA_LABELS[midiaCodigo] || 'Origem não mapeada';

// pega o item original do lead direto pelo node que o produziu (nao pelo $input,
// que aqui seria a saida do "Mailing - Ler Dados"). Esse node sempre retorna
// exatamente 1 item, entao usamos .first() em vez de .all().map() pra deixar isso explícito.
const itemOriginal = $('Identificar reunião com email do lead e preparar horário de inicio e fim1').first();

itemOriginal.json.midiaLabel = midiaLabel;
itemOriginal.json.midiaConflito = midiaConflito; // true = id e telefone divergiram, usamos o id

return [itemOriginal];

const TIMEZONE = "America/Sao_Paulo";

const leadEmailRaw = $('trigger').first().json.email;

if (!leadEmailRaw) {
  return [{
    json: {
      found: false,
      message: "Não foi possível buscar a reunião: e-mail do lead não informado."
    }
  }];
}

const leadEmail = leadEmailRaw.trim().toLowerCase();
const now = new Date();

function parseDate(obj) {
  if (!obj) return null;
  if (obj.dateTime) return new Date(obj.dateTime);
  if (obj.date) return new Date(obj.date + "T00:00:00-03:00");
  return null;
}

function getMeetingLink(ev) {
  const video = ev.conferenceData?.entryPoints?.find(e => e.entryPointType === "video");
  if (video?.uri) return video.uri;
  if (ev.hangoutLink) return ev.hangoutLink;
  if (ev.location && /^https?:\/\//i.test(ev.location.trim())) return ev.location.trim();
  return null;
}

function format(date) {
  return {
    date: date.toLocaleDateString("pt-BR", { timeZone: TIMEZONE }),
    weekday: date.toLocaleDateString("pt-BR", { timeZone: TIMEZONE, weekday: "long" }),
    time: date.toLocaleTimeString("pt-BR", { timeZone: TIMEZONE, hour: "2-digit", minute: "2-digit" })
  };
}

function build(ev, start, status) {
  return {
    eventId: ev.id,
    summary: ev.summary || "Reunião",
    status, // "em_andamento" | "agendada" | "realizada"
    ...format(start),
    meetingLink: getMeetingLink(ev)
  };
}

// Eventos do lead, não cancelados
const events = $input.all()
  .map(i => i.json)
  .filter(ev => ev?.id && ev.status !== "cancelled")
  .filter(ev => ev.attendees?.some(a => a.email?.trim().toLowerCase() === leadEmail))
  .map(ev => ({ ev, start: parseDate(ev.start), end: parseDate(ev.end) || parseDate(ev.start) }))
  .filter(e => e.start);

// Próxima = ainda não terminou (inclui a que está acontecendo agora)
const upcoming = events.filter(e => e.end > now).sort((a, b) => a.start - b.start);
const past = events.filter(e => e.end <= now).sort((a, b) => b.start - a.start);

const next = upcoming[0]
  ? build(upcoming[0].ev, upcoming[0].start, upcoming[0].start <= now ? "em_andamento" : "agendada")
  : null;
const last = past[0] ? build(past[0].ev, past[0].start, "realizada") : null;

// Mensagem pronta para o agente
let message;
if (next) {
  message = next.status === "em_andamento"
    ? `A reunião está acontecendo agora (começou às ${next.time}).`
    : `A próxima reunião é ${next.weekday}, ${next.date}, às ${next.time}.`;
  message += next.meetingLink
    ? ` Link: ${next.meetingLink}`
    : " Não há link de videochamada cadastrado nesse evento.";
} else if (last) {
  message = `Não há reunião futura agendada. A última reunião foi em ${last.date} às ${last.time}.`;
} else {
  message = "Não encontrei nenhuma reunião agendada para este e-mail.";
}

return [{
  json: {
    found: !!next,
    nextMeeting: next,
    lastMeeting: last,
    message
  }
}];
